def night_minutes(start, end, zone):
    first = datetime.fromtimestamp(start, zone).date() - timedelta(days=1)
    last = datetime.fromtimestamp(end, zone).date() + timedelta(days=1)
    total = 0
    day = first
    while day <= last:
        win_start = local_to_ts(datetime(day.year, day.month, day.day, 22), zone, 0)
        nxt = day + timedelta(days=1)
        win_end = local_to_ts(datetime(nxt.year, nxt.month, nxt.day, 6), zone, 0)
