                if pending is not None and start <= workday(pending[3]) <= end:
                    exc["open_shifts"] += 1
                pending = (ts, site, pid, rts)
            else:
                if pending is not None and rts - pending[3] <= 16 * 3600:
                    shifts.append((pending[3], rts, pending[1]))
                else:
                    if pending is not None and start <= workday(pending[3]) <= end:
                        exc["open_shifts"] += 1
                    if start <= workday(rts) <= end:
                        exc["orphan_outs"] += 1
                pending = None
        if pending is not None and start <= workday(pending[3]) <= end:
            exc["open_shifts"] += 1

