                continue
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(rin, rout, sites[site][0]), paid)
            rows.append({"in": rin, "day": day, "paid": paid, "night": night})
        rows.sort(key=lambda row: row["in"])

        daily_total = defaultdict(int)
        for row in rows:
            before = daily_total[row["day"]]
            after = before + row["paid"]
            daily_total[row["day"]] = after
            row["daily_ot"] = max(0, after - 480) - max(0, before - 480)
        week_total = defaultdict(int)
        for row in rows:
            week = row["day"] - timedelta(days=row["day"].weekday())
            base = row["paid"] - row["daily_ot"]
            before = week_total[week]
            after = before + base
            week_total[week] = after
            row["ot"] = row["daily_ot"] + max(0, after - 2400) - max(0, before - 2400)

        pay = Fraction(0)
        for row in rows:
            rate = Fraction(0)
            for effective, value in rates.get(emp, []):
                if effective <= row["day"]:
                    rate = value
            regular = row["paid"] - row["ot"]
            pay += rate * (regular + Fraction(3, 2) * row["ot"]) / 60 + rate * Fraction(15, 100) * row["night"] / 60
        result[emp] = {
            "shifts": len(rows),
            "paid_minutes": sum(row["paid"] for row in rows),
            "overtime_minutes": sum(row["ot"] for row in rows),
            "night_minutes": sum(row["night"] for row in rows),
            "gross": money(int((pay * 100 + Fraction(1, 2)) // 1)),
        }

    totals = {key: sum(v[key] for v in result.values())
              for key in ("shifts", "paid_minutes", "overtime_minutes", "night_minutes")}
    totals["gross"] = money(sum(int(v["gross"].replace(".", "")) for v in result.values()))
    summary = {"period": {"start": period["start"], "end": period["end"]}, "employees": result,
               "exceptions": exc, "totals": totals}
    Path(outfile).parent.mkdir(parents=True, exist_ok=True)
    Path(outfile).write_text(json.dumps(summary, indent=1))


