    parsed.sort(key=lambda item: (item[0], item[1]))
    applied = 0
    for _, _, rec in parsed:
        key = (rec["site"].strip(), rec["punch_id"].strip())
        action = rec["action"].strip()
        if action == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif action == "set":
            if key in punches:
                punches[key]["ts"] = to_ts(datetime.fromisoformat(rec["time"].strip()))
                applied += 1
        elif action == "add":
            if key not in ever:
                punches[key] = {"emp": rec["employee"].strip(), "dir": rec["type"].strip().upper(),
                                "ts": to_ts(datetime.fromisoformat(rec["time"].strip()))}
                ever.add(key)
                applied += 1

    by_emp = defaultdict(list)
    for (site, pid), data in punches.items():
        if data["emp"] in employees:
            by_emp[data["emp"]].append((data["ts"], 0 if data["dir"] == "OUT" else 1, site, pid, data["dir"]))

    def in_period(stamp, emp):
        day = datetime.fromtimestamp(stamp, sites[employees[emp]][0]).date()
        return day, start <= day <= end

    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0, "corrections_applied": applied}
    result = {}
    for emp in employees:
        home = sites[employees[emp]][0]
        items = sorted(by_emp.get(emp, []))
        kept = []
        for ts, _, site, pid, direction in items:
            zone = sites[site][0]
            rts = round_ts(ts, zone)
            if kept and kept[-1][4] == direction and ts - kept[-1][0] <= 300:
                if start <= datetime.fromtimestamp(rts, home).date() <= end:
                    exc["duplicates_dropped"] += 1
                continue
            kept.append((ts, site, pid, rts, direction))

        def workday(rts):
            return datetime.fromtimestamp(rts, home).date()

        shifts = []
        pending = None
        for ts, site, pid, rts, direction in kept:
            if direction == "IN":
                if pending is not None and start <= workday(pending[3]) <= end:
                    exc["open_shifts"] += 1
                pending = (ts, site, pid, rts)
            else:
                if pending is not None and rts - pending[3] <= 16 * 3600:
                    shifts.append((pending[3], rts, pending[1]))
                else:
                    if pending is not None and start <= workday(pending[3]) <= end:
                        exc["open_shifts"] += 1
                    if start <= workday(rts) <= end:
                        exc["orphan_outs"] += 1
                pending = None
        if pending is not None and start <= workday(pending[3]) <= end:
            exc["open_shifts"] += 1

        rows = []
        for rin, rout, site in shifts:
            day = workday(rin)
            if not (start <= day <= end):
                continue
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(rin, rout, sites[site][0]), paid)
            rows.append({"in": rin, "day": day, "paid": paid, "night": night})
        rows.sort(key=lambda row: row["in"])

        daily_total = defaultdict(int)
        for row in rows:
            before = daily_total[row["day"]]
            after = before + row["paid"]
            daily_total[row["day"]] = after
            row["daily_ot"] = max(0, after - 480) - max(0, before - 480)
        week_total = defaultdict(int)
        for row in rows:
            week = row["day"] - timedelta(days=row["day"].weekday())
            base = row["paid"] - row["daily_ot"]
            before = week_total[week]
            after = before + base
            week_total[week] = after
            row["ot"] = row["daily_ot"] + max(0, after - 2400) - max(0, before - 2400)

        pay = Fraction(0)
        for row in rows:
            rate = Fraction(0)
            for effective, value in rates.get(emp, []):
                if effective <= row["day"]:
                    rate = value
            regular = row["paid"] - row["ot"]
            pay += rate * (regular + Fraction(3, 2) * row["ot"]) / 60 + rate * Fraction(15, 100) * row["night"] / 60
        result[emp] = {
            "shifts": len(rows),
            "paid_minutes": sum(row["paid"] for row in rows),
            "overtime_minutes": sum(row["ot"] for row in rows),
            "night_minutes": sum(row["night"] for row in rows),
            "gross": money(int((pay * 100 + Fraction(1, 2)) // 1)),
        }

    totals = {key: sum(v[key] for v in result.values())
              for key in ("shifts", "paid_minutes", "overtime_minutes", "night_minutes")}
    totals["gross"] = money(sum(int(v["gross"].replace(".", "")) for v in result.values()))
    summary = {"period": {"start": period["start"], "end": period["end"]}, "employees": result,
               "exceptions": exc, "totals": totals}
    Path(outfile).parent.mkdir(parents=True, exist_ok=True)
    Path(outfile).write_text(json.dumps(summary, indent=1))


